actor A {
    n: int
}
actor B {
    m: int
}
impl A {
    async fun ping(self, b: B) -> int {
        return await b.pong(self)
    }
    fun val(self) -> int {
        return self.n
    }
}
impl B {
    async fun pong(self, a: A) -> int {
        return await a.val() + self.m
    }
}
#main
async fun main() {
    let a = A { n: 1 }
    let b = B { m: 2 }
    async let x = a.ping(b)
    async let y = a.ping(b)
    print(await x + await y)
}

