actor Counter {
    count: int
}
impl Counter {
    fun increment(var self) {
        let v = self.count
        var spin = 0
        while spin < 20 {
            spin = spin + 1
        }
        self.count = v + 1
    }
    fun get(self) -> int {
        return self.count
    }
}
async fun count_up(c: Counter, n: int) {
    for i in 0..n {
        await c.increment()
    }
}
