actor P {
    n: int
}
impl P {
    async fun poke(self, other: P, depth: int) -> int {
        if depth == 0 {
            return self.n
        }
        return await other.poke(self, depth - 1) + self.n
    }
}
#main
async fun main() {
    let p = P { n: 1 }
    let q = P { n: 10 }
    async let x = p.poke(q, 50)
    async let y = q.poke(p, 50)
    print(await x)
    print(await y)
}

