enum Opt { Some(int), None }
fun bump(o: Opt) -> Opt { return match o { Opt.Some(n) => Opt.Some(n + 1), Opt.None => Opt.None } }
fun peel(o: Opt) -> int { return match o { Opt.Some(n) => n, Opt.None => -1 } }
fun main() {
    print(peel(bump(Opt.Some(41))))
    print(peel(bump(Opt.None)))
}

enum Shape { Circle(int), Rect(int, int), Empty }
