struct C {
    n: int,
}
impl C {
    fun bump_get(var self) -> int {
        self.n = self.n + 1
        return self.n
    }
    fun plus(self, k: int) -> int {
        return self.n * 100 + k
    }
    fun with(self, o: C, k: int) -> int {
        return self.n * 10000 + o.n * 100 + k
    }
}
fun outer(c: C, k: int) -> int {
    return c.n * 100 + k
}
#main
fun main() {
    var c = C { n: 1 }
    print(c.plus(c.bump_get()))
    var d = C { n: 1 }
    print(outer(d, d.bump_get()))
    var xs = [C { n: 1 }]
    print(xs[0].plus(xs[0].bump_get()))
    var e = C { n: 1 }
    var f = C { n: 5 }
    print(e.with(f, f.bump_get()))
    let g = (x: C, k: int) => x.n * 100 + k
    var h = C { n: 1 }
    print(g(h, h.bump_get()))
    var p = C { n: 1 }
    print(p.n * 100 + p.bump_get())
}

